                                                                                                                                                                                                                   
  CREATE TABLE "TENANT_EVENT_APPEAL"                                                                                                                                                                    
   (	"EVENT_APPEAL_ID" NUMBER(20,0) GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,     
	"CREATED_BY" NUMBER(20,0) NOT NULL ENABLE,                                                                                                                                                                        
	"CREATION_DATE" DATE NOT NULL ENABLE,                                                                                                                                                                             
	"UPDATED_BY" NUMBER(20,0) NOT NULL ENABLE,                                                                                                                                                                        
	"UPDATE_DATE" DATE NOT NULL ENABLE,                                                                                                                                                                               
	"TENANT_ID" NUMBER(20,0) DEFAULT 3 NOT NULL ENABLE,                                                                                                                                                               
	"REMARK" NVARCHAR2(512),                                                                                                                                                                                          
	"SUBMIT_USER_ID" NUMBER(20,0),                                                                                                                                                                                    
	"SUBMIT_EXT_ORG_ID" NUMBER(20,0),                                                                                                                                                                                 
	"CONTENT" CLOB,                                                                                                                                                                                                   
	"EXPECTED_SOLUTION" NVARCHAR2(1000),                                                                                                                                                                              
	"IMAGES_URLS" CLOB,                                                                                                                                                                                               
	"STATUS" NVARCHAR2(20),                                                                                                                                                                                           
	"REPLY_EXT_USER_ID" NUMBER(20,0),                                                                                                                                                                                 
	"REPLAY_CONTENT" NVARCHAR2(1000),                                                                                                                                                                                 
	"EVENT_ID" NUMBER(20,0),                                                                                                                                                                                          
	"BASE_DEPT_ID" NVARCHAR2(36),                                                                                                                                                                                     
	 PRIMARY KEY ("EVENT_APPEAL_ID")                                                                                                                                                                                  
  USING INDEX  ENABLE                                                                                                                                                                                              
   ) ;                                                                                                                                                                                                             

